CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS workspaces (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id), email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('admin','member')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS devices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID REFERENCES workspaces(id), name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'offline', latency_ms INTEGER NOT NULL DEFAULT 0, last_seen_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS access_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE, label TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, last_used_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS tunnels (id UUID PRIMARY KEY, workspace_id UUID REFERENCES workspaces(id), device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('tcp','http')), public_port INTEGER NOT NULL UNIQUE CHECK(public_port BETWEEN 10000 AND 60000), local_host TEXT NOT NULL, local_port INTEGER NOT NULL CHECK(local_port BETWEEN 1 AND 65535), enabled BOOLEAN NOT NULL DEFAULT true, max_connections INTEGER NOT NULL DEFAULT 100);
CREATE TABLE IF NOT EXISTS audit_events (id UUID PRIMARY KEY, actor_id UUID REFERENCES users(id), action TEXT NOT NULL, subject TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
